SELECT CASE WHEN tuple_position <= 20 THEN CAST(tuple_position AS VARCHAR) WHEN tuple_position > 20 THEN '20 +' ELSE '' END AS tuple_position, COUNT(DISTINCT CASE WHEN saleschanel = 'iOS' THEN tin END) AS iOS_tin, COUNT(DISTINCT CASE WHEN saleschanel = 'Android' THEN tin END) AS Android_tin FROM ( SELECT -- CAST(DATE_TRUNC('day', at_timezone(s.__time, 'Asia/Kolkata')) AS DATE) AS doi, -- d.sort_label, s.os saleschanel, s.route_id, c.tin, (s.offset + s.position + 1) AS tuple_position FROM "user_interaction"."search_route_details" s -- LEFT JOIN "user_interaction"."search_details" d ON -- s.mri_session_id = d.mri_session_id -- and s.doj = d.doj -- AND s.mri_session_id = d.mri_session_id INNER JOIN "user_interaction"."confirm_order_details" c ON s.mri_session_id = c.mri_session_id and s.route_id = c.route_id and s.doj = c.doj WHERE s.__time >= TIMESTAMP '2026-04-11 18:30:00' AND s.__time < TIMESTAMP '2026-04-17 18:30:00' -- AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.channel IN ('MOBILE_APP') -- AND d.is_filter_applied = FALSE and d.sort < 1 AND s.operator_id NOT IN (10244, 10283, 10823, 11044, 11060, 15129, 15130, 15443, 15447, 15499, 16081, 16124, 16227, 16374, 16426, 16580, 16647, 16777, 16884, 17012, 17101, 17889, 18101, 18115, 18237, 18491, 19393, 19502, 24978, 25187, 25946, 26936, 27000, 27455, 28011, 29176, 29479, 3030, 6392, 7115, 8065) -- AND s.sl_attr = FALSE -- AND s.os = 'Android' -- AND s.os = 'iOS' -- AND CAST(src_id AS VARCHAR) || '-' || CAST(dest_id AS VARCHAR) IN ('122-123') AND s.country = 'IND' AND c.tin IS NOT NULL AND s.mri_session_id IS NOT NULL ) a GROUP BY 1 -- ,2 -- ,3 ORDER BY 1
